var o=[{title:`Jak złożone jest ćwiczenie`,text:`Wiosłowanie na maszynie z podparciem porusza się po stabilnym torze. Rumuński martwy ciąg na jednej nodze wymaga równowagi, kontroli tułowia i koordynacji bioder, a swing z kettlebell dodaje prędkość i wyczucie czasu. Możesz być bardzo silny i nadal być nowicjuszem w jednej z tych umiejętności.`},{title:`Przechodź od przewidywalnego do wymagającego`,text:`Zacznij od stabilnych pozycji i wolniejszych powtórzeń i ucz się jednej nowej umiejętności naraz. Potem utrudniaj ćwiczenie, odbierając podparcie, zmieniając dźwignię, zwiększając zakres lub dodając kontrolowaną prędkość. Progresja powinna zachowywać cel ruchu i unikać zmiany wszystkich wymagań naraz.`},{title:`Zmęczenie zmienia koordynację`,text:`Ćwiczenie, które na początku treningu wychodziło Ci dobrze, może stać się chwiejne po wielu powtórzeniach. Wykonuj ćwiczenia o wysokich wymaganiach technicznych wcześniej, odpoczywaj dłużej, gdy trzeba, i kończ serię, gdy równowaga lub kontrola słabnie. Złożone ćwiczenia balistyczne są zwykle złym pierwszym wyborem dla zmęczonego początkującego.`},{title:`Przykład`,text:`Jeśli uczysz się wykroków, możesz zacząć od przysiadów ze statycznym rozkrokiem, trzymając się poręczy, przejść do wykroków w tył bez podparcia i spróbować wykroków chodzonych później. Szybszy wariant nie jest automatycznie lepszy.`},{title:`Korzystanie z TrainUp`,text:`Gdy TrainUp buduje Twój plan, wybiera ćwiczenia pasujące do Twojego poziomu i koordynacji, a także ograniczeń i sprzętu.`}];var a=[{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026: praktyczne wskazówki`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var n={sections:o,sources:a};export{n as default,o as sections,a as sources};